parameters.jsCode:
// Mantém apenas conversas sem resposta do time há mais de 1 hora
const ONE_HOUR_MS = 60 * 60 * 1000;
const now = Date.now();
const items = $input.all();
const overdue = [];

for (const item of items) {
  const conversations = item.json.payload || item.json.data?.payload || [];
  for (const conv of conversations) {
    const lastOutgoing = conv.last_activity_at ? conv.last_activity_at * 1000 : null;
    const waitingSince = conv.waiting_since ? conv.waiting_since * 1000 : lastOutgoing;
    if (waitingSince && (now - waitingSince) > ONE_HOUR_MS) {
      overdue.push({
        json: {
          region: item.json.region,
          conversation_id: conv.id,
          contact_name: conv.meta?.sender?.name || 'desconhecido',
          minutes_waiting: Math.round((now - waitingSince) / 60000)
        }
      });
    }
  }
}

return overdue;

